before.lib/profile.ex:
defmodule Normalize do
  @moduledoc false
  def name(value), do: value |> String.trim() |> String.downcase()
end
defmodule Profile do
  @doc "Public profile name: trimmed and lowercase. Normalize is private to this application."
  def name(value), do: Normalize.name(value)
  @doc "Read a URI query's name field and apply the same public name policy."
  def from_query(query), do: query |> URI.decode_query() |> Map.fetch!("name") |> name()
end

